<div x-data="{open:false}" class="space-y-6"><div class="flex justify-between"><div><h1 class="text-3xl font-bold">Canales en vivo</h1><p class="text-slate-400">Fuentes principales y respaldos autorizados.</p></div><button @click="open=!open" class="bg-cyan-600 px-4 py-2 rounded-lg">Añadir canal</button></div>
<form x-show="open" x-cloak method="post" action="/live" class="grid md:grid-cols-4 gap-3 bg-slate-900 border border-slate-800 rounded-xl p-5"><?=$csrf->field()?><input required name="title" placeholder="Título" class="bg-slate-800 p-2 rounded"><input type="number" name="channel_number" placeholder="Número" class="bg-slate-800 p-2 rounded"><select name="category_id" class="bg-slate-800 p-2 rounded"><option value="">Categoría</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach?></select><input name="logo_url" placeholder="Logo URL" class="bg-slate-800 p-2 rounded"><input required type="url" name="source_url" placeholder="Fuente HTTP(S)" class="md:col-span-2 bg-slate-800 p-2 rounded"><input name="user_agent" placeholder="User-Agent" class="bg-slate-800 p-2 rounded"><input name="referer" placeholder="Referer" class="bg-slate-800 p-2 rounded"><textarea name="http_headers" placeholder='Headers JSON: {"X-Key":"valor"}' class="md:col-span-2 bg-slate-800 p-2 rounded"></textarea><input name="cookies" placeholder="Cookies (se cifran)" class="bg-slate-800 p-2 rounded"><label class="flex items-center gap-2"><input type="checkbox" name="authorized" value="1"> Fuente autorizada</label><select name="delivery_mode" class="bg-slate-800 p-2 rounded"><option value="on_demand">On-demand</option><option value="always_on">Always-on</option></select><label class="flex items-center gap-2"><input type="checkbox" name="transcode_enabled"> Transcodificar</label><button class="md:col-span-4 bg-cyan-600 p-2 rounded">Guardar canal</button></form>
<div class="grid gap-4"><?php foreach($channels as $channel):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><div class="flex justify-between"><div><h2 class="text-xl font-bold">#<?=htmlspecialchars((string)($channel['channel_number']??'—'))?> <?=htmlspecialchars($channel['title'])?></h2><p class="text-slate-400"><?=htmlspecialchars($channel['category']??'Sin categoría')?> · <?=htmlspecialchars($channel['delivery_mode'])?></p></div><span><?=htmlspecialchars($channel['status'])?></span></div><div class="mt-4 space-y-2"><?php foreach($channel['sources'] as $source):?><div class="flex gap-3 text-sm bg-slate-950 p-2 rounded"><strong>P<?=$source['priority']?></strong><span><?=htmlspecialchars($source['name'])?></span><span class="<?=$source['authorized']?'text-emerald-400':'text-red-400'?>"><?=$source['authorized']?'Autorizada':'Bloqueada'?></span><span class="ml-auto"><?=htmlspecialchars($source['status'])?></span></div><?php endforeach?></div><form method="post" action="/live/source" class="mt-4 grid md:grid-cols-5 gap-2"><?=$csrf->field()?><input type="hidden" name="channel_id" value="<?=$channel['id']?>"><input name="name" placeholder="Respaldo" class="bg-slate-800 p-2 rounded"><input required type="url" name="source_url" placeholder="URL respaldo" class="md:col-span-2 bg-slate-800 p-2 rounded"><input type="number" min="1" name="priority" value="100" class="bg-slate-800 p-2 rounded"><label class="flex items-center gap-2"><input type="checkbox" name="authorized"> Autorizada</label><button class="md:col-span-5 bg-slate-700 p-2 rounded">Añadir fuente de respaldo</button></form></article><?php endforeach?></div></div>
